def write(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def packed(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(gzip.compress(f.canonical(v),mtime=0))
def seal(p):
    write(p/'manifest.json',dict(kind=g.KIND,previous_source_revision=g.REVISION,tools=[dict(path=x,sha256=f.sha((g.ROOT/x).read_bytes())) for x in g.TOOLS],sources=[dict(path=x,sha256=f.sha((g.ROOT/x).read_bytes())) for x in g.SOURCES],artifacts={x.relative_to(p).as_posix():f.sha(x.read_bytes()) for x in sorted(p.rglob('*')) if x.is_file() and x!=p/'manifest.json'}))
def prepare(p,syntax_binary,flow_binary):
    p.mkdir(parents=True);inputs,functions=g.source_inputs();raw=json.dumps(inputs,ensure_ascii=False).encode();packed(p/'private/source-inputs.json.gz',inputs)
    for label,binary,helper in [('syntax',syntax_binary,'scripts/wi2_source_syntax.go.txt'),('flow',flow_binary,'scripts/wi1_dev_source.go.txt')]:
        r=subprocess.run([str(binary)],input=raw,capture_output=True,timeout=120);write(p/(label+'-receipt.json'),dict(argv=[str(binary)],exit_code=r.returncode,executable_sha256=f.sha(binary.read_bytes()),helper_sha256=f.sha((g.ROOT/helper).read_bytes()),stdin_sha256=f.sha(raw),stdout_sha256=f.sha(r.stdout),stderr_sha256=f.sha(r.stderr),candidate_engine_imported_or_invoked=False));(p/(label+'-stdout.json.gz')).write_bytes(gzip.compress(r.stdout,mtime=0));(p/(label+'-stderr.txt')).write_bytes(r.stderr);r.check_returncode()
    syntax=f.packed(p/'syntax-stdout.json.gz');observations=f.packed(p/'flow-stdout.json.gz');by_s={(s['path'],s['span']['start']):s for s in syntax};by_o={(o['path'],o['span']['start']):o for o in observations}
    public=g.public_inputs(functions,syntax);write(p/'public/controlled-DEV.json',[r for r in public if r['stratum']=='controlled']);write(p/'public/project-DEV.json',[r for r in public if r['stratum']=='project'])
    for fn in functions:
        dest=p/'public/source'/(fn['id']+'.go.txt');dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(fn['code'].encode())
