if __name__=='__main__':
    a=argparse.ArgumentParser();a.add_argument('--syntax-binary',type=Path,required=True);a.add_argument('--flow-binary',type=Path,required=True);a.add_argument('--output',type=Path,default=g.ROOT/g.PACKET);v=a.parse_args();prepare(v.output,v.syntax_binary,v.flow_binary)
